//! The standard fonts annotation text is set in (spec 06 section 5): the
//! 12 non-symbolic standard Type 1 faces of ISO 32000-2 §9.6.2.2, the /DA
//! resource names that stand for them, their advances in WinAnsiEncoding
//! (Annex D), and WinAnsi encoding itself.
//!
//! Each face measures with its own metrics (decisions A4 and A8): the
//! advance and glyph-box data at the end of this file is generated by
//! `engine/generate/annots_fonts.py` from Adobe's Core 14 AFM files, whose
//! notice it carries. The WinAnsi code of each glyph name comes from the
//! engine's Annex D table (`forms::text`).
use std::sync::OnceLock;

use crate::app::forms::text::{Family, Metrics, win_ansi_code, win_ansi_name};
use crate::object::{Dictionary, Object};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Base14 {
    Helvetica,
    HelveticaBold,
    HelveticaOblique,
    HelveticaBoldOblique,
    TimesRoman,
    TimesBold,
    TimesItalic,
    TimesBoldItalic,
    Courier,
    CourierBold,
    CourierOblique,
    CourierBoldOblique,
}

/// One face's WinAnsi metrics: per code, the advance (1/1000 em) and the
/// bottom and top of the glyph's box; zeros for codes without a glyph.
struct Table {
    codes: [[i16; 3]; 256],
    /// The highest top and lowest bottom of the face's WinAnsi glyphs.
    top: i16,
    bottom: i16,
}

impl Base14 {
    const ALL: [Self; 12] = [
        Self::Helvetica,
        Self::HelveticaBold,
        Self::HelveticaOblique,
        Self::HelveticaBoldOblique,
        Self::TimesRoman,
        Self::TimesBold,
        Self::TimesItalic,
        Self::TimesBoldItalic,
        Self::Courier,
        Self::CourierBold,
        Self::CourierOblique,
        Self::CourierBoldOblique,
    ];

    fn index(self) -> usize {
        Self::ALL.iter().position(|f| *f == self).unwrap_or(0)
    }

    /// The face a /DA font resource name stands for (section 5.1): the
    /// names of Acrobat's AcroForm default resources and the /BaseFont
    /// names; anything else is Helvetica.
    pub fn from_resource_name(name: &[u8]) -> Self {
        match name {
            b"HeBo" | b"Helvetica-Bold" => Self::HelveticaBold,
            b"HeOb" | b"Helvetica-Oblique" => Self::HelveticaOblique,
            b"HeBO" | b"Helvetica-BoldOblique" => Self::HelveticaBoldOblique,
            b"TiRo" | b"Times-Roman" => Self::TimesRoman,
            b"TiBo" | b"Times-Bold" => Self::TimesBold,
            b"TiIt" | b"Times-Italic" => Self::TimesItalic,
            b"TiBI" | b"Times-BoldItalic" => Self::TimesBoldItalic,
            b"Cour" | b"Courier" => Self::Courier,
            b"CoBo" | b"Courier-Bold" => Self::CourierBold,
            b"CoOb" | b"Courier-Oblique" => Self::CourierOblique,
            b"CoBO" | b"Courier-BoldOblique" => Self::CourierBoldOblique,
            _ => Self::Helvetica,
        }
    }

    /// The standard /BaseFont name (ISO 32000-2 §9.6.2.2).
    pub fn base_font(self) -> &'static [u8] {
        match self {
            Self::Helvetica => b"Helvetica",
            Self::HelveticaBold => b"Helvetica-Bold",
            Self::HelveticaOblique => b"Helvetica-Oblique",
            Self::HelveticaBoldOblique => b"Helvetica-BoldOblique",
            Self::TimesRoman => b"Times-Roman",
            Self::TimesBold => b"Times-Bold",
            Self::TimesItalic => b"Times-Italic",
            Self::TimesBoldItalic => b"Times-BoldItalic",
            Self::Courier => b"Courier",
            Self::CourierBold => b"Courier-Bold",
            Self::CourierOblique => b"Courier-Oblique",
            Self::CourierBoldOblique => b"Courier-BoldOblique",
        }
    }

    fn table(self) -> &'static Table {
        static TABLES: [OnceLock<Table>; 12] = [const { OnceLock::new() }; 12];
        let index = self.index();
        TABLES[index].get_or_init(|| {
            let face = &METRICS[index];
            let mut codes = [[0i16; 3]; 256];
            let (mut top, mut bottom) = (0i16, 0i16);
            for (code, slot) in codes.iter_mut().enumerate() {
                let Some(name) = u8::try_from(code).ok().and_then(win_ansi_name) else {
                    continue;
                };
                if let Ok(at) = GLYPHS.binary_search(&name) {
                    *slot = face[at];
                    bottom = bottom.min(slot[1]);
                    top = top.max(slot[2]);
                }
            }
            Table { codes, top, bottom }
        })
    }

    /// Advance of WinAnsi code `byte` in 1/1000 em; 0 for codes the face
    /// does not draw (control codes, undefined WinAnsi codes).
    pub fn advance(self, byte: u8) -> f64 {
        f64::from(self.table().codes[usize::from(byte)][0])
    }

    /// Width of WinAnsi `bytes` at `size`: sum of advances × size / 1000.
    pub fn width(self, bytes: &[u8], size: f64) -> f64 {
        let units: f64 = bytes.iter().map(|&b| self.advance(b)).sum();
        units * size / 1000.0
    }

    /// /Type /Font /Subtype /Type1 /BaseFont <base_font> /Encoding
    /// /WinAnsiEncoding.
    pub fn dictionary(self) -> Dictionary {
        let mut font = Dictionary::new();
        font.insert(b"Type".to_vec(), Object::name("Font"));
        font.insert(b"Subtype".to_vec(), Object::name("Type1"));
        font.insert(b"BaseFont".to_vec(), Object::name(self.base_font()));
        font.insert(b"Encoding".to_vec(), Object::name("WinAnsiEncoding"));
        font
    }

    /// The face's WinAnsi advances as the shared layout measures them.
    pub(crate) fn metrics(self) -> Metrics {
        Metrics::from_widths((0..=255u8).map(|b| self.advance(b)).collect())
    }

    /// The standard family whose 8-bit fallback fonts go with this face.
    pub(crate) fn family(self) -> Family {
        match self {
            Self::Helvetica | Self::HelveticaOblique => Family::Helvetica,
            Self::HelveticaBold | Self::HelveticaBoldOblique => Family::HelveticaBold,
            Self::TimesRoman | Self::TimesBold | Self::TimesItalic | Self::TimesBoldItalic => {
                Family::Times
            }
            Self::Courier | Self::CourierBold | Self::CourierOblique | Self::CourierBoldOblique => {
                Family::Courier
            }
        }
    }

    /// The top and bottom (em) of every WinAnsi glyph of the face: no
    /// glyph rises above `.0` or falls below `.1` of its baseline.
    pub(crate) fn glyph_box(self) -> (f64, f64) {
        let table = self.table();
        (
            f64::from(table.top) / 1000.0,
            f64::from(table.bottom) / 1000.0,
        )
    }

    /// The top and bottom (em) of the glyphs of WinAnsi `bytes`; (0, 0)
    /// when none has ink.
    pub(crate) fn extent(self, bytes: &[u8]) -> (f64, f64) {
        let table = self.table();
        let (mut top, mut bottom) = (0i16, 0i16);
        for &b in bytes {
            let [_, lo, hi] = table.codes[usize::from(b)];
            top = top.max(hi);
            bottom = bottom.min(lo);
        }
        (f64::from(top) / 1000.0, f64::from(bottom) / 1000.0)
    }
}

/// The WinAnsiEncoding code of `c` (Annex D), if any: U+0020–U+007E and
/// U+00A0–U+00FF are their own byte, and the characters of 0x80–0x9F come
/// from Annex D's glyph names; control characters have none.
pub fn win_ansi(c: char) -> Option<u8> {
    if c < ' ' || c == '\u{7F}' {
        return None;
    }
    win_ansi_code(c)
}

/// `text` as WinAnsi bytes: a C0 control character (< U+0020) is kept as
/// its byte; any other character without a code becomes `?`.
pub fn encode(text: &str) -> Vec<u8> {
    text.chars()
        .map(|c| {
            if c < ' ' {
                c as u8
            } else {
                win_ansi(c).unwrap_or(b'?')
            }
        })
        .collect()
}

