#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_win_ansi_glyph_has_a_width_in_every_face() {
        for face in Base14::ALL {
            for code in 0..=255u8 {
                let named = win_ansi_name(code).is_some();
                assert_eq!(face.advance(code) > 0.0, named, "{face:?} {code:#x}");
            }
            let (top, bottom) = face.glyph_box();
            assert!(top > 0.7 && top < 1.0 && bottom < -0.1 && bottom > -0.3);
        }
        assert_eq!(Base14::Helvetica.extent(b"AV"), (0.718, 0.0));
        assert_eq!(encode("a\u{7}é?日"), [b'a', 7, 0xE9, b'?', b'?']);
        assert_eq!(win_ansi('\u{AD}'), Some(0xAD));
        assert_eq!(win_ansi('\u{7F}'), None);
    }
}
